// The sign-in popup lands here with a one-time code. Hand it to the window that opened the popup (the frame),
// with the target origin pinned to the platform origin, then close (docs/03-architecture.qrmd, "Sign-in").
const params = new URLSearchParams(location.search)
const code = params.get('code')
const error = params.get('error_description') || params.get('error')
const msg = document.getElementById('msg')!
const target = location.origin
const opener = window.opener as Window | null
if (opener) {
  opener.postMessage({ type: 'yrS4:auth', code, error }, target)
  msg.textContent = error ? `Sign-in failed: ${error}` : 'Signed in. You can close this window.'
  if (!error) setTimeout(() => window.close(), 300)
} else {
  msg.textContent = error ? `Sign-in failed: ${error}` : 'Sign-in finished, but this window was not opened by the subjexts panel. Close it and try again from the book.'
}
history.replaceState(null, '', location.pathname)
